//! Code as lines of spans, each tagged with what it is (`TokenKind`), never with a colour: each app
//! colours the kinds by its own light and dark palettes.
//!
//! Lexing runs through `@pierre/highlights` compiled from WebAssembly to C (`vendor/highlights/`,
//! regenerated by `scripts/generate-highlights.sh`). Highlighting is bounded by size, not by a
//! clock: it stops at `MAX_HIGHLIGHT_LINES`, `MAX_HIGHLIGHT_BYTES`, or a line longer than
//! `MAX_HIGHLIGHT_LINE_BYTES`, and every line from that point on is plain text.

mod engine;
mod generated;
mod kinds;
mod languages;
#[cfg(test)]
mod tests;

pub use self::languages::{language_for_path, language_label, normalize_language};

pub const MAX_HIGHLIGHT_LINES: usize = 5_000;
pub const MAX_HIGHLIGHT_BYTES: usize = 512 * 1024;
pub const MAX_HIGHLIGHT_LINE_BYTES: usize = 4_096;

#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum TokenKind {
    Plain,
    Comment,
    Keyword,
    String,
    Number,
    /// `true`, `null`, a character literal, an escape, a language constant.
    Constant,
    Type,
    Function,
    /// A parameter, or `self`/`this`.
    Variable,
    /// A key of JSON, YAML, TOML or CSS.
    Property,
    Operator,
    Punctuation,
    /// An HTML or XML tag name.
    Tag,
    Attribute,
    /// A diff's added and removed lines.
    Inserted,
    Deleted,
    /// A markdown heading, a diff's hunk header.
    Heading,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct CodeSpan {
    pub text: String,
    pub kind: TokenKind,
}

/// One line without its line break. Neighbouring spans differ in kind; an empty line has no span.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct CodeLine {
    pub spans: Vec<CodeSpan>,
}

/// `code` in lines of spans. `language` is a fence label (`ts`, `bash`), a file extension, or a
/// name `language_for_path` returned; an unknown or absent one makes every line plain.
pub fn highlight(code: &str, language: Option<&str>) -> Vec<CodeLine> {
    let Some(lang_id) = language.and_then(languages::language_id) else {
        return split_lines(code).map(plain_line).collect();
    };
    let cut = bounded_prefix(code);
    let mut lines = if cut > 0 {
        match engine::tokenize(&code[..cut], lang_id) {
            Some(highlighted) => highlighted,
            None => return split_lines(code).map(plain_line).collect(),
        }
    } else {
        Vec::new()
    };
    lines.extend(split_lines(&code[cut..]).map(plain_line));
    lines
}

/// Byte offset of the prefix within the highlight line, total-byte, and per-line bounds.
fn bounded_prefix(code: &str) -> usize {
    let mut offset = 0;
    for (count, line) in code.split_inclusive('\n').enumerate() {
        let over = count >= MAX_HIGHLIGHT_LINES
            || offset + line.len() > MAX_HIGHLIGHT_BYTES
            || line.len() > MAX_HIGHLIGHT_LINE_BYTES;
        if over {
            break;
        }
        offset += line.len();
    }
    offset
}

fn split_lines(text: &str) -> impl Iterator<Item = &str> {
    text.split_inclusive('\n')
        .map(|line| line.strip_suffix('\n').unwrap_or(line))
        .map(|line| line.strip_suffix('\r').unwrap_or(line))
}

fn plain_line(line: &str) -> CodeLine {
    let spans = if line.is_empty() {
        Vec::new()
    } else {
        vec![CodeSpan {
            text: line.to_owned(),
            kind: TokenKind::Plain,
        }]
    };
    CodeLine { spans }
}
